INSERT INTO `hw_details_secteur` VALUES (1,1,'Santé','sante','Fluidifiez le parcours patient & optimisez le temps médical','<ul class=\"sect-exp-sols\">\r\n	<li>Rappels automatiques SMS/WhatsApp</li>\r\n	<li>Confirmation patient interactive</li>\r\n	<li>Optimisation agenda m&eacute;decin</li>\r\n	<li>Gestion proactive des no-shows</li>\r\n</ul>\r\n\r\n<p><span class=\"sect-exp-kpi\">&minus;40% d&#39;absent&eacute;isme &middot; RDV 24/7</span></p>\r\n',NULL,'Santé','Santé','fr'),(2,2,'Restauration','restauration','Digitalisez l\'expérience client, de la réservation à la commande','<ul class=\"sect-exp-sols\">\r\n	<li>Prise de commande WhatsApp automatis&eacute;e</li>\r\n	<li>Menu dynamique &amp; r&eacute;servations intelligentes</li>\r\n	<li>Rappel de panier moyen</li>\r\n	<li>Upselling automatis&eacute; boissons/desserts</li>\r\n</ul>\r\n\r\n<p><span class=\"sect-exp-kpi\">Ticket moyen +15% &middot; Z&eacute;ro perte d&#39;appel</span></p>\r\n',NULL,'Restauration','Restauration','fr'),(3,3,'Hôtellerie','hotellerie','Conciergerie multilingue 24/7 & réservations directes boostées','<ul class=\"sect-exp-sols\">\r\n	<li>Booking conversationnel multilingue</li>\r\n	<li>Confirmation instantan&eacute;e de r&eacute;servation</li>\r\n	<li>Upsell chambres/services</li>\r\n	<li>Check-in/out express automatis&eacute;</li>\r\n</ul>\r\n\r\n<p><span class=\"sect-exp-kpi\">Commissions OTA r&eacute;duites &middot; R&eacute;ponse &lt;1 min</span></p>\r\n',NULL,'Hôtellerie','Hôtellerie','fr'),(4,4,'Immobilier','immobilier','Qualifiez vos leads en temps réel & informez vos acquéreurs','<ul class=\"sect-exp-sols\">\r\n	<li>Mises &agrave; jour chantier quotidiennes</li>\r\n	<li>Scraping/veille march&eacute; automatis&eacute;</li>\r\n	<li>Campagnes WhatsApp vers prospects chauds</li>\r\n	<li>Qualification t&eacute;l&eacute;phonique des leads</li>\r\n</ul>\r\n\r\n<p><span class=\"sect-exp-kpi\">Conversion lead-to-visit +30%</span></p>\r\n',NULL,'Immobilier','Immobilier','fr'),(5,5,'Finance','finance','Automatisez votre intelligence de marché & vos flux d\'exécution','<ul class=\"sect-exp-sols\">\r\n	<li>Agent Forex &amp; Or (signaux Telegram)</li>\r\n	<li>Alertes news et sentiment march&eacute;</li>\r\n	<li>Suivi intelligent des re&ccedil;us/d&eacute;penses</li>\r\n	<li>Ex&eacute;cution en millisecondes</li>\r\n</ul>\r\n\r\n<p><span class=\"sect-exp-kpi\">Z&eacute;ro erreur humaine &middot; Tra&ccedil;abilit&eacute; totale</span></p>\r\n',NULL,'Finance','Finance','fr'),(6,6,'Marketing','marketing','Industrialisez votre veille, rapports & distribution de contenus','<ul class=\"sect-exp-sols\">\r\n	<li>Suivi positions SEO Google automatis&eacute;</li>\r\n	<li>Rapport marketing hebdomadaire</li>\r\n	<li>G&eacute;n&eacute;ration de tableaux de m&eacute;triques</li>\r\n	<li>Publication omnicanal automatis&eacute;e</li>\r\n</ul>\r\n\r\n<p><span class=\"sect-exp-kpi\">10h/semaine &eacute;conomis&eacute;es &middot; Production &times;5</span></p>\r\n',NULL,'Marketing','Marketing','fr'),(7,7,'Opérations','operations','Brisez les silos & assistez vos équipes au quotidien','<ul class=\"sect-exp-sols\">\r\n	<li>Organisation Gmail et alertes urgentes</li>\r\n	<li>Synth&egrave;se Trello par projet</li>\r\n	<li>Digest deadlines vers Slack</li>\r\n	<li>Analyse enregistrements Zoom</li>\r\n</ul>\r\n\r\n<p><span class=\"sect-exp-kpi\">Perte d&#39;info r&eacute;duite &agrave; 0% &middot; R&eacute;unions &divide;2</span></p>\r\n',NULL,'Opérations','Opérations','fr'),(8,8,'Opérations','operations-1','Brisez les silos & assistez vos équipes au quotidien','<ul class=\"sect-exp-sols\">\r\n	<li>Organisation Gmail et alertes urgentes</li>\r\n	<li>Synth&egrave;se Trello par projet</li>\r\n	<li>Digest deadlines vers Slack</li>\r\n	<li>Analyse enregistrements Zoom</li>\r\n</ul>\r\n\r\n<p><span class=\"sect-exp-kpi\">Perte d&#39;info r&eacute;duite &agrave; 0% &middot; R&eacute;unions &divide;2</span></p>\r\n',NULL,'Opérations','Opérations','fr');
